import java.util.*;

public class Main {
    static final int MOD = 1000000007;
    static List<Integer>[] adj;
    static int[] color;
    static int nodeCount;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s1 = sc.next();
        String s2 = sc.next();
        int N = s1.length();

        Map<Character, Integer> dominoId = new HashMap<>();
        int id = 0;
        for (char c : s1.toCharArray()) if (!dominoId.containsKey(c)) dominoId.put(c, id++);
        for (char c : s2.toCharArray()) if (!dominoId.containsKey(c)) dominoId.put(c, id++);

        int numDominoes = id;
        Set<Integer>[] adjSet = new HashSet[numDominoes];
        for (int i = 0; i < numDominoes; i++) adjSet[i] = new HashSet<>();

        char[][] grid = new char[2][N];
        for (int j = 0; j < N; j++) { grid[0][j] = s1.charAt(j); grid[1][j] = s2.charAt(j); }

        int[][] dirs = {{0,1},{1,0}};
        for (int r = 0; r < 2; r++) {
            for (int c = 0; c < N; c++) {
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr < 2 && nc < N) {
                        int a = dominoId.get(grid[r][c]), b = dominoId.get(grid[nr][nc]);
                        if (a != b) { adjSet[a].add(b); adjSet[b].add(a); }
                    }
                }
            }
        }

        adj = new List[numDominoes];
        for (int i = 0; i < numDominoes; i++) adj[i] = new ArrayList<>(adjSet[i]);

        color = new int[numDominoes];
        Arrays.fill(color, -1);
        boolean[] visited = new boolean[numDominoes];

        long ans = 1;
        for (int start = 0; start < numDominoes; start++) {
            if (!visited[start]) {
                List<Integer> comp = new ArrayList<>();
                Queue<Integer> q = new LinkedList<>();
                q.add(start); visited[start] = true;
                while (!q.isEmpty()) {
                    int u = q.poll(); comp.add(u);
                    for (int v : adj[u]) if (!visited[v]) { visited[v] = true; q.add(v); }
                }
                long ways = countColorings(comp);
                ans = ans * ways % MOD;
            }
        }
        System.out.println(ans);
    }

    static long countColorings(List<Integer> comp) {
        int[] nodes = comp.stream().mapToInt(x->x).toArray();
        int n = nodes.length;
        int[] c = new int[n];
        Arrays.fill(c, -1);
        return solve(nodes, c, 0);
    }

    static long solve(int[] nodes, int[] c, int idx) {
        if (idx == nodes.length) return 1;
        long count = 0;
        for (int col = 0; col < 3; col++) {
            boolean ok = true;
            for (int nb : adj[nodes[idx]]) {
                // find nb in nodes
                for (int k = 0; k < idx; k++) {
                    if (nodes[k] == nb && c[k] == col) { ok = false; break; }
                }
                if (!ok) break;
            }
            if (ok) {
                c[idx] = col;
                count += solve(nodes, c, idx + 1);
                c[idx] = -1;
            }
        }
        return count % MOD;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        String s1 = fs.next();
        String s2 = fs.next();

        List<Integer> types = new ArrayList<>(); // 0 = vertical, 1 = horizontal pair
        int i = 0;
        while (i < N) {
            if (s1.charAt(i) == s2.charAt(i)) {
                types.add(0);
                i++;
            } else {
                types.add(1);
                i += 2;
            }
        }

        long ans;
        if (types.get(0) == 0) ans = 3;
        else ans = 6;

        for (int k = 1; k < types.size(); k++) {
            int prev = types.get(k - 1);
            int cur = types.get(k);

            if (prev == 0 && cur == 0) {
                ans = ans * 2 % MOD;
            } else if (prev == 0 && cur == 1) {
                ans = ans * 2 % MOD;
            } else if (prev == 1 && cur == 0) {
                ans = ans * 1 % MOD;
            } else { // prev == 1 && cur == 1
                ans = ans * 3 % MOD;
            }
        }

        System.out.println(ans % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
